def babylonian_squareroot(n):
    if n < 0:
        raise ValueError("Cannot compute square root of negative number")
    if n == 0:
        return 0

    guess = n / 2.0
    tolerance = 1e-15

    while True:
        new_guess = (guess + n / guess) / 2.0
        if abs(new_guess - guess) < tolerance:
            break
        guess = new_guess

    return new_guess

